function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Background: Green hills
  brush.fill("#57a50a"); // Green
  brush.beginShape(0.7); // Curvature
  brush.vertex(0, 200); // Top of hill
  brush.vertex(400, 100); // Bottom of hill
  brush.vertex(0, 300); // Top of hill
  brush.endShape(true);

  // Sun
  brush.fill("#ff8c6a"); // Orange sun
  brush.beginShape(0.6);
  brush.vertex(100, 250); // Top of sun
  brush.vertex(300, 100); // Bottom of sun
  brush.vertex(100, 450); // Top of sun
  brush.endShape(true);

  // Sunset
  brush.fill("#d97b8b"); // Pink
  brush.beginShape(0.5); // Curvature
  brush.vertex(0, 200); // Top of sunset
  brush.vertex(400, 200); // Bottom of sunset
  brush.vertex(0, 400); // Top of sunset
  brush.endShape(true);
}
