Here's how you could paint a sunset over green hills using the p5.brush library:

```javascript
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Painting goes here
  brush.fill("#ffe3b3", 100); // Sky
  brush.fill("#00953f", 100); // Sun

  // Hill - a series of shaded circles for the hill
  brush.fill("#87cefa", 60); // Grass
  brush.fill("#006600", 60); // Grass-green color
  brush.circle(0, 400, 300); // Left hill
  brush.fill("#92f8e6", 50); // Wind-blown grass (light green)
  brush.fill("#879e5d", 50); // Soft green blur
  brush.beginShape();
  brush.vertex(200, 350); // Top of hill
  brush.vertex(200, 300); // Bottom of hill
  brush.vertex(400, 300); // Right of hill
  brush.vertex(400, 100); // Left of hill
  brush.endShape(true); // End of the shape

  // Sun - a large filled circle to indicate the sun
  brush.fill("#ffffff", 255); // White for sun
  brush.fill("#ffffff", 255); // Fill with solid white
  brush.fill("#000000", 30); // Define a small black border
  brush.beginShape();
  brush.vertex(400, 50); // Top of sun
  brush.vertex(150, 250); // Bottom of sun
  brush.vertex(200, 120); // Right of sun
  brush.vertex(200, 180); // Left of sun
  brush.endShape(true);
}
```

