  brush.beginShape(1.5);
  brush.vertex(0, 0); // Top left of hill
  brush.vertex(400, 0); // Top right of hill
  brush.vertex(200, 400); // Bottom center of hill
  brush.vertex(0, 400); // Bottom left of hill
  brush.endShape(true);

  // Middle hill (green)
  brush.fill("#00FF00", 200); // Green
  brush.beginShape(1.2);
  brush.vertex(200, 100); // Top of hill
  brush.vertex(250, 200); // Right side of hill
  brush.vertex(350, 100); // Bottom of hill
  brush.vertex(400, 100); // Left side of hill
  brush.endShape(true);

  // Bottom hill (green)
  brush.fill("#00FF00", 100); // Green
  brush.beginShape(1.0);
  brush.vertex(200, 200); // Top of hill
  brush.vertex(250, 300); // Right side of hill
  brush.vertex(350, 200); // Bottom of hill
  brush.vertex(400, 200); // Left side of hill
  brush.endShape(true);

  // Sun (orange) on top of the hills
