function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // painting goes here
  stroke("#e08a72", 75);
  curveGradientEntry.clearRect(1, 1, 40, 30);
  curveGradientEntry.createChannel("stop", 0, 0, 150, "#f4efe4");
  curveGradientEntry.createChannel("stop", 2, 20, 250, "#888d4c");
  strokeGradientEntry = curl;
  // do our curves here
  drawCentralCrumbs();
  drawGrasshopper();
  drawHills();

  // call all shapes in reverse order to draw back to front
  brush.noStroke();
  brush.fill("#888d4c", 75);  // green
  brush.fill("#f4efe4", 100);  // sky
  brush.stroke("#e08a72", 10); // orange
  brush.beginShape();
  brush.vertex(0, 0); // top of the sun
  brush.vertex(200, 40); // top of the sun's left
  brush.vertex(400, 0); // top of the sun
  brush.vertex(200, 40); // top of the sun's right
  brush.endShape(true);

  // sunset
  strokeGradientEntry = curl;
  // do our curves here
  drawCentralCrumbs();
  drawGrasshopper();
  drawHills();
  stroke("#e08a72", 15);
  // draw sun
  brush.stroke("#e08a72", 75);
  brush.beginShape();
  brush.vertex(0, 0); // top of the sun
  brush.vertex(200, 40); // top of the sun
  brush.vertex(400, 0); // top of the sun
  brush.vertex(200, 40); // top of the sun
  brush.endShape(true);

  brush.noFill();
  brush.fillBleed(0.5); // anti-alias
  brush.fillTexture(1, 50); // some texture
}
```

