  brush.vertex(200, 40); // top of the sun's left
  brush.vertex(400, 0); // top of the sun
  brush.vertex(200, 40); // top of the sun's right
  brush.endShape(true);

  // sunset
  strokeGradientEntry = curl;
  // do our curves here
  drawCentralCrumbs();
  drawGrasshopper();
  drawHills();
  stroke("#e08a72", 15);
  // draw sun
  brush.stroke("#e08a72", 75);
  brush.beginShape();
  brush.vertex(0, 0); // top of the sun
  brush.vertex(200, 40); // top of the sun
  brush.vertex(400, 0); // top of the sun
  brush.vertex(200, 40); // top of the sun
  brush.endShape(true);

  brush.noFill();
  brush.fillBleed(0.5); // anti-alias
  brush.fillTexture(1, 50); // some texture
