Here's how you could paint a sunset over green hills using the `p5.brush` library:

```javascript
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fillBleed(100);  // Create a border
  brush.beginShape();
  brush.vertex(300, 0);    // Top-left hill
  brush.vertex(400, 200); // Top-right hill
  brush.vertex(400, 150); // Top-middle hill
  brush.endShape(true);
  brush.fillBleed(0);    // Set the blend back to normal

  brush.beginShape();
  brush.vertex(300, 200); // Middle-left hill
  brush.vertex(400, 100); // Middle-right hill
  brush.vertex(500, 150); // Middle-middle hill
  brush.endShape(true);

  // Paint the hills with the sunset color
  brush.fill("#e8c893", 50); // Sunset color with 50% opacity
  brush.brush();
  brush.beginShape();
  brush.vertex(200, 50);  // Left hill
  brush.vertex(300, 30); // Bottom-left hill
  brush.vertex(400, 20); // Bottom-right hill
  brush.endShape(true);
  brush.noStroke();
  brush.fill("#f3e4a6", 60); // Ocean color with 60% opacity
  brush.brush();
  brush.beginShape();
  brush.vertex(50, 150);   // Top-left hill
  brush.vertex(200, 50);  // Top-middle hill
  brush.vertex(300, 150); // Top-right hill
  brush.endShape(true);

  // Paint the clouds and sun
  brush.fill("#ffffff", 20); // White clouds
  brush.brush();
  brush.beginShape();
  brush.vertex(200, 200);  // Center of the sun
  brush.vertex(100, 100);  // Left half of the sun
  brush.vertex(300, 100);  // Right half of the sun
  brush.endShape(true);

  brush.noStroke();
  brush.fill("#ffc678", 30); // Sun color with 30% opacity
}
```

