  brush.fill("#008B8B", 50); // Green
  brush.fillBleed(0.5); // Bleed effect
  brush.beginShape();
  brush.vertex(100, 200); // Top-left hill
  brush.vertex(400, 200); // Top-right hill
  brush.vertex(400, 0); // Top-right hill
  brush.vertex(100, 0); // Top-left hill
  brush.endShape(true); // End of hill

  // Paint the sun
  brush.fill("#FFA07A", 100); // Yellow
  brush.beginShape();
  brush.vertex(200, 100); // Sun's center
  brush.vertex(100, 50); // Sun's top
  brush.vertex(200, 50); // Sun's top
