function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fill("#f4c2c2", 255); // sun color
  brush.beginShape(0.8); // curvature of the sun
  brush.vertex(0, 0); // top of the sun
  brush.vertex(400, 0); // bottom of the sun
  brush.vertex(400, 200); // right side of the sun
  brush.endShape(true); // close the shape

  // Paint the green hills
  brush.noStroke();
  brush.fill("#008000", 128); // green color for hills
  brush.beginShape(0.5); // curvature of the hills
  brush.vertex(0, 200); // top of the hills
  brush.vertex(200, 100); // bottom of the hills
  brush.vertex(400, 200); // right side of the hills
  brush.endShape(true); // close the shape
}
